fails = 0
for ver, what, f, pat, present in CHECKS:
    ok = has(f, pat) == present
    fails += not ok
    print(f"{'OK  ' if ok else 'MISSING'} {ver:8} {what}")
print(f"\n{len(CHECKS) - fails}/{len(CHECKS)} decisions in place")
sys.exit(1 if fails else 0)
